/// Health transitions from the isolated quota lane. The payload is retained
/// only for a successful observation; failures are intentionally categorical
/// so a malformed app-server response cannot leak into recorder diagnostics.
#[derive(Clone, PartialEq)]
pub enum QuotaPollEvent {
    Ready {
        snapshot: QuotaSnapshot,
        login_id: String,
        epoch: AccountEpochProof,
    },
    /// Acquisition and account verification succeeded, but the saved input
    /// requires interpretation. This is not a transport/storage failure.
    InputStored {
        login_id: String,
        epoch: AccountEpochProof,
    },
    Failed,
}

impl fmt::Debug for QuotaPollEvent {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Ready { snapshot, .. } => formatter
                .debug_struct("QuotaPollEvent::Ready")
                .field("snapshot", snapshot)
                .field("login_id", &"[redacted]")
                .finish(),
            Self::Failed => formatter.write_str("QuotaPollEvent::Failed"),
            Self::InputStored { .. } => formatter.write_str("QuotaPollEvent::InputStored"),
        }
    }
}

/// Polls the Codex app-server in a lane independent of Session collection.
/// A failed poll is reported as degraded while the last good quota remains
/// available to the next recorder cycle.
pub struct QuotaPoller {
    receiver: Receiver<QuotaPollResult>,
    worker: Option<JoinHandle<()>>,
    stopping: Arc<AtomicBool>,
    latest: Option<QuotaPollCandidate>,
    events: Vec<QuotaPollEvent>,
}

impl QuotaPoller {
    pub fn start() -> Self {
        Self::start_with_interval(DEFAULT_INTERVAL_SECS)
    }

    /// Start the quota lane with the caller's polling cadence. The worker
    /// never waits on the Session recorder. Every response is journaled before
    /// this queue; coalescing notifications cannot discard the acquisition.
    pub fn start_with_interval(interval_secs: u64) -> Self {
        let (sender, receiver) = mpsc::sync_channel(2);
        let interval_secs = interval_secs.max(1);
        let stopping = Arc::new(AtomicBool::new(false));
        let worker_stopping = Arc::clone(&stopping);
        let worker = thread::spawn(move || {
            let mut schedule = FixedRateSchedule::new(Duration::from_secs(interval_secs));
            while !worker_stopping.load(Ordering::Acquire) {
                let result = fetch_quota_snapshot(&sender);
                match sender.try_send(result) {
                    Ok(()) | Err(TrySendError::Full(_)) => {}
                    Err(TrySendError::Disconnected(_)) => break,
                }
                let wait = schedule.complete_cycle(Instant::now());
                if wait.missed_deadlines != 0 {
                    eprintln!(
                        "recorder quota sampling overrun: missed_deadlines={}",
                        wait.missed_deadlines
                    );
                }
                let deadline = Instant::now() + wait.sleep_for;
                while !worker_stopping.load(Ordering::Acquire) {
                    let Some(remaining) = deadline.checked_duration_since(Instant::now()) else {
                        break;
                    };
                    // Recheck the deadline after a spurious wake. Shutdown
                    // wakes this wait without shortening normal cadence.
                    thread::park_timeout(remaining);
                }
            }
        });
        Self {
            receiver,
            worker: Some(worker),
            stopping,
            latest: None,
            events: Vec::new(),
        }
    }

    pub fn latest(&mut self) -> Option<QuotaPollCandidate> {
        while let Ok(result) = self.receiver.try_recv() {
            match result {
                Ok(success) => {
                    if let Some(snapshot) = success.snapshot {
                        self.latest = Some(QuotaPollCandidate {
                            snapshot: snapshot.clone(),
                            epoch: success.epoch.clone(),
                        });
                        self.events.push(QuotaPollEvent::Ready {
                            snapshot,
                            login_id: success.login_id,
                            epoch: success.epoch,
                        });
                    } else {
                        self.events.push(QuotaPollEvent::InputStored {
                            login_id: success.login_id,
                            epoch: success.epoch,
                        });
                    }
                }
                Err(error) => {
                    eprintln!("recorder degraded: quota poll failed: {error}");
                    self.events.push(QuotaPollEvent::Failed);
                }
            }
        }
        self.latest.clone()
    }

    /// Drain health transitions without waiting for a poll result. The main
    /// loop can forward these to the DB health API while continuing Session
    /// collection when the app-server lane is degraded.
    pub fn take_events(&mut self) -> Vec<QuotaPollEvent> {
        std::mem::take(&mut self.events)
    }
}

impl Drop for QuotaPoller {
    fn drop(&mut self) {
        self.stopping.store(true, Ordering::Release);
        if let Some(worker) = self.worker.take() {
            let began = Instant::now();
            eprintln!("codex-info-recorder diagnostic quota_drain start");
            worker.thread().unpark();
            // A normal process exit cannot abandon the response owned by
            // fetch_quota_snapshot, including a pending journal write.
            if worker.join().is_err() {
                eprintln!("recorder degraded: quota worker terminated unexpectedly");
            }
            eprintln!(
                "codex-info-recorder diagnostic quota_drain finish elapsed_ms={}",
                began.elapsed().as_millis()
            );
        }
    }
}

