    #[test]
    fn recorder_account_identity_contract_authority_is_exact_and_redacted() {
        let authority = parse_account_authority(
            br#"{"email":"person@example.invalid","tokens":{"account_id":"authority-1","access_token":"opaque"}}"#,
        )
        .expect("valid account authority");
        assert!(authority.account_id.0 == b"authority-1");

        let debug = format!("{authority:?}");
        assert!(!debug.contains("person@example.invalid"));
        assert!(!debug.contains("opaque"));
        assert!(!debug.contains("authority-1"));

        assert!(parse_account_authority(
            br#"{"tokens":{"account_id":"authority-1","account_id":"authority-2"}}"#,
        )
        .is_err());
        assert!(parse_account_authority(br#"{"tokens":{"account_id":1}}"#).is_err());
        assert!(parse_account_authority(br#"{"tokens":{"account_id":""}}"#).is_err());
    }

    #[test]
    fn recorder_auth_state_requires_an_exact_consistent_account_shape() {
        assert_eq!(
            decode_codex_authentication_state(&json!({
                "account": null,
                "requiresOpenaiAuth": true
            })),
            Ok(CodexAuthenticationState::AuthRequired)
        );
        // OpenAI app-server auth example: requiresOpenaiAuth describes the
        // provider's credential requirement, independently of the account.
        for requires in [true, false] {
            assert_eq!(
                decode_codex_authentication_state(&json!({
                    "account":{"type":"chatgpt","email":"current@example.com","planType":"pro"},
                    "requiresOpenaiAuth":requires,
                })),
                Ok(CodexAuthenticationState::Authenticated)
            );
        }
        for inconsistent in [
            json!({"account": null, "requiresOpenaiAuth": false}),
            json!({
                "account": {
                    "type": "apiKey"
                },
                "requiresOpenaiAuth": true
            }),
            json!({"account":null}),
            json!({"account":{"type":"chatgpt","email":"current@example.com","planType":"pro"},"requiresOpenaiAuth":"true"}),
            json!({"account":{"type":"chatgpt","email":null,"planType":"pro"},"requiresOpenaiAuth":true}),
        ] {
            assert!(decode_codex_authentication_state(&inconsistent).is_err());
        }
    }

    #[test]
    fn recorder_auth_state_idle_publication_has_no_account_or_generation_authority() {
        let root = temp_root("idle-no-account-state");
        fs::create_dir_all(root.join("history")).expect("history directory");
        let lease = ProfileLease::acquire(&root).expect("profile lease");
        let mut writer = RecorderStateWriter::new_idle(&root, &lease).expect("idle writer");
        writer
            .write_idle_no_account()
            .expect("idle recorder publication");

        let value: Value = serde_json::from_slice(
            &fs::read(root.join("history/recorder-state.json")).expect("idle state"),
        )
        .expect("idle state JSON");
        assert_eq!(value["write_state"], "idle_no_account");
        // The root distribution manifest is the version authority, independent
        // of the recorder publication implementation and its package version.
        let expected_version = include_str!("../../../Cargo.toml")
            .lines()
            .find_map(|line| line.strip_prefix("version = \""))
            .expect("distribution version")
            .trim_end_matches('"');
        assert_eq!(value["recorder_version"], expected_version);
        for field in [
            "partition_id_hash",
            "data_generation",
            "collector_epoch",
            "cycle_seq",
            "last_commit_unix",
        ] {
            assert!(value[field].is_null(), "{field}");
        }
        let boundary = RecorderStateWriter::read_previous_authority(&root)
            .expect("idle previous authority")
            .expect("idle boundary fingerprint");
        assert!(boundary.partition_id.is_none());
        assert_eq!(boundary.transition_fingerprint.len(), 64);

        drop(writer);
        drop(lease);
        fs::remove_dir_all(root).expect("idle state cleanup");
    }

    #[test]
    fn recorder_account_identity_contract_window_rejects_authority_and_account_changes() {
        let authority = AccountAuthority {
            account_id: AccountAuthorityId::from_str("authority-1").unwrap(),
        };
        let account = AppServerAccount {
            email: "person@example.invalid".to_owned(),
            plan_type: "pro".to_owned(),
        };
        let window = AccountIdentityWindow::new(authority.clone(), account.clone());
        assert!(window.is_stable(&authority, &account));

        let changed_authority = AccountAuthority {
            account_id: AccountAuthorityId::from_str("authority-2").unwrap(),
        };
        assert!(!window.is_stable(&changed_authority, &account));

        let changed_account = AppServerAccount {
            email: "other@example.invalid".to_owned(),
            ..account.clone()
        };
        assert!(!window.is_stable(&authority, &changed_account));
    }

