    #[test]
    fn exhausted_cycle_budget_does_not_mark_sources_already_at_eof_as_backlog() {
        let (root, database) = prepare("budget-eof");
        let first_source = root.join("sessions/a.jsonl");
        let second_source = root.join("sessions/b.jsonl");
        let now = Utc::now().timestamp();
        let time = DateTime::<Utc>::from_timestamp(now - 2, 0)
            .unwrap()
            .to_rfc3339();
        let proven_source = |id: &str, total| {
            format!(
                "{}\n{}\n{}{}",
                json!({"type":"session_meta","timestamp":time,"payload":{"id":id}}),
                json!({"type":"turn_context","timestamp":time,"payload":{"model":"gpt-6-astra"}}),
                token(0, now - 1),
                token(total, now)
            )
        };
        fs::write(&first_source, proven_source("first", 10)).unwrap();
        fs::write(&second_source, proven_source("second", 20)).unwrap();
        let mut recorder =
            Recorder::open_partitioned(config(&root, 4096), &database, &identity()).unwrap();
        assert_eq!(recorder.run_cycle().unwrap().unwrap().pending_ranges, 0);
        drop(recorder);
        fs::OpenOptions::new()
            .append(true)
            .open(&first_source)
            .unwrap()
            .write_all(token(15, now + 1).as_bytes())
            .unwrap();
        let mut recorder =
            Recorder::open_partitioned(config(&root, 1), &database, &identity()).unwrap();

        let report = recorder.run_cycle().unwrap().unwrap();

        assert_eq!(report.accepted_ranges, 1);
        assert_eq!(report.pending_ranges, 0);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn oversized_nonusage_is_streamed_and_following_token_is_recovered() {
        let (root, database) = prepare("oversized");
        let source = root.join("sessions/one.jsonl");
        let now = Utc::now().timestamp();
        let huge = format!(
            "{{\"type\":\"response_item\",\"timestamp\":\"{}\",\"payload\":{{\"type\":\"function_call_output\",\"output\":\"{}\"}}}}\n",
            DateTime::<Utc>::from_timestamp(now, 0)
                .unwrap()
                .to_rfc3339(),
            "x".repeat(4 * 1024 * 1024 + 1)
        );
        let metadata = "{\"type\":\"session_meta\",\"payload\":{\"id\":\"large-thread\",\"session_id\":\"large-session\"}}\n";
        fs::write(&source, format!("{metadata}{}{}", huge, token(20, now))).unwrap();
        let mut recorder =
            Recorder::open_partitioned(config(&root, 128), &database, &identity()).unwrap();
        assert_eq!(recorder.run_cycle().unwrap().unwrap().accepted_ranges, 1);
        assert_eq!(recorder.run_cycle().unwrap().unwrap().accepted_ranges, 1);
        fs::OpenOptions::new()
            .append(true)
            .open(&source)
            .unwrap()
            .write_all(token(25, now + 1).as_bytes())
            .unwrap();
        recorder.run_cycle().unwrap().unwrap();
        let events = recorder.writer.load_session_events().unwrap();
        assert_eq!(events.len(), 1);
        assert_eq!(events[0].total_tokens, 5);
        assert_eq!(events[0].timestamp, now + 1);
        assert_eq!(events[0].model, UNATTRIBUTED_MODEL);
        assert!(
            recorder.model_totals().unwrap().is_empty(),
            "unassigned usage is internal evidence"
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn terminated_malformed_record_does_not_poison_following_tokens() {
        let (root, database) = prepare("malformed-following-token");
        let source = root.join("sessions/one.jsonl");
        let now = Utc::now().timestamp();
        fs::write(
            &source,
            format!(
                "{{\"unterminated\":}}\n{}{}",
                token(10, now),
                token(15, now + 1)
            ),
        )
        .unwrap();
        let mut recorder =
            Recorder::open_partitioned(config(&root, 1024), &database, &identity()).unwrap();
        let first = recorder.run_cycle().unwrap().unwrap();
        assert_eq!(first.pending_ranges, 1);
        assert_eq!(
            recorder.model_totals().unwrap()[UNATTRIBUTED_MODEL].total,
            5
        );
        assert!(!recorder.state().unwrap().checkpoints[0].fully_attributed_from_zero);
        let pending: (i64, String, i64) = Connection::open(&database)
            .unwrap()
            .query_row(
                "SELECT COUNT(*), reason, complete FROM session_pending_ranges",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(pending, (1, "malformed-json-record".to_owned(), 1));
        assert_eq!(recorder.generation().unwrap(), 1);
        let heartbeat = recorder.run_cycle().unwrap().unwrap();
        assert_eq!(heartbeat.accepted_ranges, 0);
        assert_eq!(heartbeat.generation, 2);
        assert_eq!(recorder.generation().unwrap(), 2);
        assert_eq!(
            recorder.model_totals().unwrap()[UNATTRIBUTED_MODEL].total,
            5
        );
        let pending_count: i64 = Connection::open(&database)
            .unwrap()
            .query_row("SELECT COUNT(*) FROM session_pending_ranges", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(pending_count, 1);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn fresh_quota_outage_commits_events_then_materializes_after_quota_recovery() {
        let (root, database) = prepare("fresh-quota-outage");
        let source = root.join("sessions/one.jsonl");
        let now = Utc::now().timestamp();
        fs::write(&source, token(10, now)).unwrap();
        Connection::open(&database)
            .unwrap()
            .execute(
                "UPDATE collection_generation
                 SET reset_at=0, latest_quota_reset_at=0, window_seconds=0",
                [],
            )
            .unwrap();
        let mut recorder =
            Recorder::open_partitioned(config(&root, 1024), &database, &identity()).unwrap();

        let first = recorder.run_cycle_with_quota(None).unwrap().unwrap();
        assert_eq!(first.generation, 1);
        assert_eq!(first.accepted_ranges, 1);
        assert!(recorder.model_totals().unwrap().is_empty());
        fs::OpenOptions::new()
            .append(true)
            .open(&source)
            .unwrap()
            .write_all(token(15, now + 1).as_bytes())
            .unwrap();
        let second = recorder.run_cycle_with_quota(None).unwrap().unwrap();
        assert_eq!(second.generation, 2);
        assert_eq!(second.accepted_ranges, 1);
        assert!(recorder.model_totals().unwrap().is_empty());
        let event_count: i64 = Connection::open(&database)
            .unwrap()
            .query_row("SELECT COUNT(*) FROM session_events", [], |row| row.get(0))
            .unwrap();
        assert_eq!(event_count, 1);

        let recovered = recorder
            .run_cycle_with_quota(Some(QuotaSnapshot {
                observed_at: now + 2,
                reset_at: now + 3600,
                window_seconds: 3600,
                remaining_percent: Some(82.0),
            }))
            .unwrap()
            .unwrap();
        assert_eq!(recovered.generation, 3);
        assert_eq!(
            recorder.model_totals().unwrap()[UNATTRIBUTED_MODEL].total,
            5
        );
        assert_eq!(recorder.state().unwrap().reset_at, now + 3600);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn official_reset_identity_replaces_stale_local_period() {
        const WINDOW: i64 = 7 * 24 * 60 * 60;
        const RESET: i64 = 1_792_044_505;
        const OBSERVED: i64 = 1_791_691_140;
        let state = SessionCollectionState {
            data_generation: 76797,
            reset_at: RESET,
            latest_quota_reset_at: RESET,
            window_seconds: WINDOW,
            last_quota_observation: Some(codex_info_db_writer::SessionQuotaObservation {
                observed_at: OBSERVED,
                remaining_percent: 10.0,
            }),
            ..SessionCollectionState::default()
        };
        // Exact provider identity is the oracle. None of these local timing
        // or percentage relationships can invalidate the official response.
        for (reset_at, observed_at, remaining, transition) in [
            (
                1_792_295_861,
                OBSERVED + 1500,
                99.0,
                QuotaTransition::Boundary,
            ),
            (RESET + 1, OBSERVED, 9.0, QuotaTransition::Boundary),
            (RESET - 1, OBSERVED + 60, 5.0, QuotaTransition::Boundary),
            (RESET + 60, OBSERVED - 60, 100.0, QuotaTransition::Boundary),
            (RESET, OBSERVED, 100.0, QuotaTransition::SamePeriod),
            (RESET, OBSERVED + 60, 99.0, QuotaTransition::SamePeriod),
        ] {
            let candidate = QuotaSnapshot {
                observed_at,
                reset_at,
                window_seconds: WINDOW,
                remaining_percent: Some(remaining),
            };
            assert_eq!(
                admit_quota_period(&state, &candidate),
                Some((transition, reset_at, reset_at, WINDOW)),
                "official reset={reset_at} observed={observed_at} remaining={remaining}"
            );
        }
    }

    #[test]
    fn issue_637_journal_replay_keeps_old_unresolved_input_without_poisoning_current_quota() {
        let (root, database) = prepare("issue637-journal-current");
        let scope = identity().account_scope_id;
        let save = |id: &str, observed_at: i64, payload: Value| {
            let receipt =
                quota_journal::QuotaReceipt::new(observed_at, Some(scope.clone()), "pro", &payload)
                    .with_id(id.repeat(32));
            receipt.save(&root, true).unwrap();
        };
        let payload = |used: i64| {
            json!({"rateLimits": {
                "primary": {"usedPercent": 0, "resetsAt": null, "windowDurationMins": null},
                "secondary": {
                    "usedPercent": used, "resetsAt": 1800604800_i64, "windowDurationMins": 10080
                }
            }})
        };
        save("aa", 1_800_000_000, json!({"unrecognized": true}));
        save("bb", 1_800_000_060, payload(0));
        let mut recorder =
            Recorder::open_partitioned(config(&root, 1024), &database, &identity()).unwrap();
        assert!(matches!(
            recorder.replay_quota_journal(&root, &scope, || false),
            Err(RecorderError::AccountBoundaryChanged)
        ));
        let db = Connection::open(&database).unwrap();
        db.execute_batch("CREATE TRIGGER reject_receipt BEFORE INSERT ON quota_receipts BEGIN SELECT RAISE(ABORT,'fixture'); END;").unwrap();
        assert!(recorder
            .replay_quota_journal(&root, &scope, || true)
            .is_err());
        assert_eq!(
            db.query_row("SELECT COUNT(*) FROM quota_receipts", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            0
        );
        db.execute_batch("DROP TRIGGER reject_receipt").unwrap();
        let replay = recorder
            .replay_quota_journal(&root, &scope, || true)
            .unwrap();
        assert_eq!(
            replay.unresolved, 1,
            "old raw input is retained for later interpretation"
        );
        let current = recorder.writer.latest_quota_receipt().unwrap().unwrap();
        assert_eq!(
            (
                current.sequence,
                current.reset_at,
                current.remaining_percent
            ),
            (2, 1_800_604_800, 100.0)
        );
        let degraded = || {
            db.query_row("SELECT COALESCE((SELECT degraded OR input_degraded FROM quota_acquisition_state WHERE singleton=1),0)", [], |r| r.get::<_, i64>(0)).unwrap()
        };
        assert_eq!(
            degraded(),
            0,
            "an old uninterpretable response cannot veto a later accepted response"
        );
        drop(recorder);
        let mut recorder =
            Recorder::open_partitioned(config(&root, 1024), &database, &identity()).unwrap();
        let replay = recorder
            .replay_quota_journal(&root, &scope, || true)
            .unwrap();
        assert_eq!(replay.unresolved, 1);
        assert_eq!(
            replay.generation, None,
            "restart must not reapply accepted input"
        );
        assert_eq!(degraded(), 0);
        save("cc", 1_800_000_120, json!({"unrecognized": true}));
        recorder
            .replay_quota_journal(&root, &scope, || true)
            .unwrap();
        assert_eq!(degraded(), 1, "the latest input really is unrecognized");
        // A subsequent successful acquisition owns recovery. Its clock may
        // move backwards; durable acquisition sequence still owns current.
        save("dd", 1_800_000_030, payload(1));
        let replay = recorder
            .replay_quota_journal(&root, &scope, || true)
            .unwrap();
        assert_eq!(replay.unresolved, 2);
        assert_eq!(degraded(), 0);
        let current = recorder.writer.latest_quota_receipt().unwrap().unwrap();
        assert_eq!(
            (
                current.sequence,
                current.observed_at,
                current.remaining_percent
            ),
            (4, 1_800_000_030, 99.0)
        );
        recorder
            .run_cycle_with_stored_quota_guarded(|| true)
            .unwrap();
        assert_eq!(recorder.state().unwrap().reset_at, 1_800_604_800);
        let journal = Connection::open(root.join("history/quota/observations.sqlite3")).unwrap();
        assert_eq!(
            journal
                .query_row("SELECT COUNT(*) FROM quota_observations", [], |r| r
                    .get::<_, i64>(0))
                .unwrap(),
            4
        );
        drop(journal);
        drop(db);
        drop(recorder);
        fs::remove_dir_all(root).unwrap();
    }

